# Basic if/elif/else
score = 85

if score >= 90:
    grade = 'A'
elif score >= 80:
    grade = 'B'
elif score >= 70:
    grade = 'C'
else:
    grade = 'F'

print(f'Grade: {grade}')  # Grade: B

# Ternary expression
status = 'pass' if score >= 60 else 'fail'
print(status)  # pass

# Truthy/Falsy
name = ''
if name:
    print(f'Hello, {name}')
else:
    print('No name provided')  # prints this
